package dev.pro8.homeview.direct;
import android.content.Context;import android.util.AtomicFile;import org.json.*;import java.io.*;import java.net.*;import java.util.*;
/** Only non-secret settings are imported, through the ADB-only activity. */
final class SetupImport {
 static File folder(Context c)throws IOException{File f=c.getExternalFilesDir("setup");if(f==null)throw new IOException("配置目录暂不可用");if(!f.isDirectory()&&!f.mkdirs())throw new IOException("无法建立配置目录");return f;}
 static File source(Context c,String name)throws Exception{if(name==null||!name.matches("setup-[a-f0-9]{32}\\.json"))throw new IllegalArgumentException("配置文件名称不正确");File dir=folder(c).getCanonicalFile(),f=new File(dir,name).getCanonicalFile();if(!dir.equals(f.getParentFile())||java.nio.file.Files.isSymbolicLink(f.toPath()))throw new IllegalArgumentException("配置路径不正确");return f;}
 static JSONObject read(File f)throws Exception{if(!f.isFile()||f.length()>16384)throw new IOException("配置文件不存在或过大");try(InputStream in=new FileInputStream(f)){return new JSONObject(new String(NetEaseClient.read(in,16384),"UTF-8"));}}
 static void write(File f,JSONObject data)throws Exception{AtomicFile a=new AtomicFile(f);FileOutputStream out=null;try{out=a.startWrite();out.write(data.toString().getBytes("UTF-8"));a.finishWrite(out);}catch(Exception e){if(out!=null)a.failWrite(out);throw e;}}
 static JSONObject validate(JSONObject value)throws Exception{
  Set<String> allowed=new HashSet<>(Arrays.asList("schema","weather","keyboard","family","set_home","idle","media","wallpaper"));for(Iterator<String> it=value.keys();it.hasNext();)if(!allowed.contains(it.next()))throw new IllegalArgumentException("配置包含不支持字段，请勿放入账号凭据");
  if(value.optInt("schema",1)!=1)throw new IllegalArgumentException("配置版本不支持");
  String keyboard=value.optString("keyboard","preserve");if(!keyboard.equals("preserve")&&!keyboard.equals("fcitx"))throw new IllegalArgumentException("输入法选项不正确");
  JSONObject family=value.optJSONObject("family");if(family==null)family=new JSONObject();for(Iterator<String> it=family.keys();it.hasNext();){String k=it.next();if(!k.equals("provider")&&!k.equals("ha_url")&&!k.equals("name"))throw new IllegalArgumentException("家庭配置只接受来源和地址");}
  String mode=family.optString("provider","preserve");if(!Arrays.asList("preserve","mijia","ha").contains(mode))throw new IllegalArgumentException("家庭来源不正确");JSONObject f=new JSONObject().put("provider",mode);
  if(mode.equals("ha")){String raw=family.optString("ha_url").trim();URI u=new URI(raw);int port=u.getPort();if(raw.length()>1024||!("http".equals(u.getScheme())||"https".equals(u.getScheme()))||u.getHost()==null||u.getUserInfo()!=null||u.getQuery()!=null||u.getFragment()!=null||!(u.getPath().isEmpty()||u.getPath().equals("/"))||port!=-1&&(port<1||port>65535))throw new IllegalArgumentException("HA 地址不正确，不要填写账号、密码或令牌");f.put("ha_url",u.getScheme()+"://"+u.getRawAuthority());}
  if(family.has("name")){String n=family.getString("name").trim();if(n.isEmpty()||n.codePointCount(0,n.length())>24)throw new IllegalArgumentException("家庭名称不正确");for(int i=0;i<n.length();i++)if(Character.isISOControl(n.charAt(i)))throw new IllegalArgumentException("家庭名称不正确");f.put("name",n);}
  JSONObject result=new JSONObject().put("schema",1).put("keyboard",keyboard).put("family",f).put("set_home",value.optBoolean("set_home",true));
  if(value.has("weather")&&!value.isNull("weather"))result.put("weather",LocalWeather.normalize(value.getJSONObject("weather")));
  if(value.has("idle")&&!value.isNull("idle")){JSONObject idle=value.getJSONObject("idle"),patch=new JSONObject();if(idle.length()==0)throw new IllegalArgumentException("待机设置为空");for(Iterator<String> it=idle.keys();it.hasNext();){String k=it.next();if(k.equals("mode")&&Arrays.asList("photos","dim","off").contains(idle.getString(k)))patch.put(k,idle.getString(k));else if(k.equals("minutes")&&idle.get(k) instanceof Integer&&Arrays.asList(1,3,5,10).contains(idle.getInt(k)))patch.put(k,idle.getInt(k));else throw new IllegalArgumentException("待机设置不正确");}result.put("idle",patch);}
  JSONArray media=value.optJSONArray("media");Set<String> sources=new HashSet<>();if(media!=null){if(media.length()>30)throw new IllegalArgumentException("图片数量过多");for(int i=0;i<media.length();i++){JSONObject m=media.getJSONObject(i);if(m.length()!=2||!m.getString("file").matches("HomeView-[a-f0-9]{32}\\.(png|jpg|webp)")||!m.getString("source").matches("HomeView-[a-f0-9]{32}\\.(png|jpg|webp)")||!sources.add(m.getString("source")))throw new IllegalArgumentException("图片记录不正确");}result.put("media",media);}
  if(value.has("wallpaper")){String wall=value.getString("wallpaper");if(!sources.contains(wall))throw new IllegalArgumentException("请选择已导入的壁纸");result.put("wallpaper",wall);}return result;
 }
 static String summary(JSONObject c)throws Exception{JSONObject weather=c.optJSONObject("weather"),family=c.getJSONObject("family");String mode=family.getString("provider");return "天气城市："+(weather==null?"保留现有 / 稍后选择":weather.getString("name"))+"\n输入法："+(c.getString("keyboard").equals("fcitx")?"小企鹅（电脑端选择）":"保留系统默认")+"\n家庭来源："+(mode.equals("ha")?"Home Assistant\n地址："+family.getString("ha_url"):mode.equals("mijia")?"Pro8 内置米家":"保留现有 / 稍后选择")+"\n\n账号仍需在设备上自行登录。应用配置会重新打开 HomeView。";}
 static void result(Context c,String name,String status,String message)throws Exception{File input=source(c,name);write(new File(input.getParentFile(),name.replace(".json",".result.json")),new JSONObject().put("status",status).put("message",message));}
 static void stage(Context c,String name,JSONObject data)throws Exception{write(new File(c.getFilesDir(),"pending-desktop-setup.json"),new JSONObject().put("name",name).put("config",validate(data)));}
 static File webFile(Context c){return new File(c.getFilesDir(),"pending-desktop-web.json");}
 static String webScript(Context c)throws Exception{if(!webFile(c).isFile())return null;JSONObject plan=read(webFile(c)),idle=plan.getJSONObject("idle");return "(function(){try{var p="+idle.toString()+",s={};try{s=JSON.parse(localStorage.getItem('hv-idle')||'{}')||{}}catch(e){};Object.keys(p).forEach(function(k){s[k]=p[k]});localStorage.setItem('hv-idle',JSON.stringify(s));return true}catch(e){return false}})()";}
 static void finishWeb(Context c,boolean ok){try{JSONObject p=read(webFile(c));String name=p.getString("name");result(c,name,ok?"ok":"error",ok?"电脑端配置已应用":"待机设置保存失败，请重试");if(ok){webFile(c).delete();source(c,name).delete();}}catch(Exception ignored){}}
 static void importPhotos(Context c,JSONObject config)throws Exception{JSONArray media=config.optJSONArray("media");if(media==null||media.length()==0)return;File dir=folder(c);LocalAlbum album=new LocalAlbum(c);AlbumFolder helper=new AlbumFolder(c,album);try{synchronized(album){JSONArray manifest=album.manifest();if(manifest.length()+media.length()>2000)throw new IOException("相册已满");long total=0;for(int i=0;i<media.length();i++){JSONObject item=media.getJSONObject(i);File file=new File(dir,item.getString("file"));if(java.nio.file.Files.isSymbolicLink(file.toPath())||!file.isFile()||file.length()>24L*1024*1024||!file.getCanonicalFile().getParentFile().equals(dir.getCanonicalFile()))throw new IOException("图片文件无效");total+=file.length();if(total>200L*1024*1024)throw new IOException("图片总量过大");String original=item.getString("source"),id=AlbumFolder.id(original);JSONObject photo=helper.prepare(file,id);File shared=new File(android.os.Environment.getExternalStoragePublicDirectory(android.os.Environment.DIRECTORY_PICTURES),"HomeView/"+original);photo.put("source",original).put("source_size",file.length()).put("source_mtime",shared.lastModified()).put("t",System.currentTimeMillis()/1000.0);manifest.put(photo);}album.saveManifest(manifest);if(config.has("wallpaper")){LocalAppearance initial=new LocalAppearance(c,album),desktop=new LocalAppearance(c,album,initial);desktop.change(new JSONObject().put("t","album").put("id",AlbumFolder.id(config.getString("wallpaper"))).put("name","电脑导入的壁纸"));}for(int i=0;i<media.length();i++)new File(dir,media.getJSONObject(i).getString("file")).delete();}}finally{helper.close();album.close();}}
 static void applyPending(Context c){File pending=new File(c.getFilesDir(),"pending-desktop-setup.json");if(!pending.isFile())return;String name="",step="读取配置";try{JSONObject plan=read(pending);name=plan.getString("name");JSONObject config=validate(plan.getJSONObject("config"));step="导入图片";importPhotos(c,config);step="保存天气";if(config.has("weather")){LocalWeather w=new LocalWeather(c);try{w.change(config.getJSONObject("weather"));}finally{w.close();}}step="保存家庭";JSONObject family=config.getJSONObject("family");String mode=family.getString("provider");android.content.SharedPreferences.Editor prefs=c.getSharedPreferences("homeview_pro8",0).edit();if(mode.equals("ha"))prefs.putString("ha_url",family.getString("ha_url"));if(family.has("name"))prefs.putString("home_name",family.getString("name"));if(!prefs.commit())throw new IOException("家庭设置保存失败");if(!mode.equals("preserve")&&!c.getSharedPreferences("homeview_family",0).edit().putString("provider",mode).commit())throw new IOException("家庭来源保存失败");if(config.has("idle"))write(webFile(c),new JSONObject().put("name",name).put("idle",config.getJSONObject("idle")));else{result(c,name,"ok","电脑端配置已应用");source(c,name).delete();}pending.delete();}catch(Exception e){try{if(!name.isEmpty())result(c,name,"error","配置未完成（"+step+" / "+e.getClass().getSimpleName()+"），请在电脑端重试");}catch(Exception ignored){}pending.delete();android.util.Log.e("HomeViewSetup","Desktop setup failed");}}
}
